#rf-root,.hf-root{--x3:#d6cfc3;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-pushout 0.5s cubic-bezier(.76,0,.24,1) 4.5s both;}.cam{position:absolute;inset:0;animation:st-cam 5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.tk{position:absolute;left:110px;right:110px;top:330px;height:1220px;border-radius:48px;background:var(--rf-accent);color:var(--rf-bg);box-shadow:0 40px 80px -40px rgba(0,0,0,.6);overflow:hidden;animation:tk-in 1.1s cubic-bezier(.16,1,.3,1) 0.1s both}
@keyframes tk-in{from{transform:translateY(200px);opacity:0}}
.tk-top{padding:70px 70px 40px;height:760px;display:flex;flex-direction:column}
.tk-tag{align-self:flex-start;font:500 28px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;padding:16px 22px;border-radius:12px;border:3px solid currentColor}
.tk-ev{margin-top:auto;font-size:112px;font-weight:600;letter-spacing:-.05em;line-height:.92}
.tk-meta{margin-top:44px;display:flex;flex-direction:column;gap:18px;font-size:40px;font-weight:600}
.tk-meta span{display:flex;align-items:center;gap:16px}
.tk-cut{height:0;border-top:6px dashed color-mix(in srgb,var(--rf-bg) 45%,transparent);margin:0 50px;position:relative}
.tk-cut::before,.tk-cut::after{content:"";position:absolute;top:-50px;width:100px;height:100px;border-radius:50%;background:var(--rf-bg)}
.tk-cut::before{left:-110px}.tk-cut::after{right:-110px}
.tk-bot{display:flex;align-items:center;gap:50px;padding:60px 70px}
.qr{display:grid;grid-template-columns:repeat(9,30px);gap:4px;padding:18px;background:var(--rf-bg);border-radius:18px}
.qr i{width:30px;height:30px;border-radius:4px}.qr i.on{background:var(--rf-text)}
.tk-no{font:600 32px/1.5 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace}.tk-no b{font-size:26px;opacity:.7}

#rf-root,.hf-root{--x3:#d6cfc3;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-pushin 0.55s cubic-bezier(.76,0,.24,1) both,st-fadeout 0.5s ease-in 5.5s both;}.cam{position:absolute;inset:0;animation:st-cam 6s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.eb{display:inline-block;font:500 32px/1.2 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}.acc{color:var(--rf-accent);font-style:normal}.wrap>div:first-child{margin-bottom:40px}
h2{margin:0 0 64px;font-size:96px;line-height:1;letter-spacing:-.04em;font-weight:var(--rf-heading-weight)}
ul{list-style:none;margin:0;padding:0}
li{display:flex;align-items:center;gap:36px;font-size:52px;line-height:1.15;font-weight:500;padding:32px 36px;margin-bottom:24px;border-radius:28px;background:var(--rf-surface);border:2px solid color-mix(in srgb,var(--rf-text) 8%,transparent)}
.mk2{flex:0 0 88px;height:88px;border-radius:20px;background:color-mix(in srgb,var(--rf-text) 8%,transparent);display:flex;align-items:center;justify-content:center;color:var(--rf-accent)}
.mk2.x{color:var(--rf-muted)}
.mk2 b{font:600 40px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace}
.mk2 svg{width:58px;height:58px;fill:none;stroke:currentColor;stroke-width:4;stroke-linecap:round;stroke-linejoin:round}
.mk2 path{stroke-dasharray:1;stroke-dashoffset:1;animation:ck .45s cubic-bezier(.16,1,.3,1) both}
@keyframes ck{to{stroke-dashoffset:0}}
